using System.Text.Json;
public class User { public int Id { get; set; } public string Email { get; set; } = ""; public string Role { get; set; } = ""; public string Salt { get; set; } = ""; public string Hash { get; set; } = ""; }
public class Facility { public int Version { get; set; } = 1; public string? ImageUrl { get; set; } public int Id { get; set; } public string Name { get; set; } = ""; public string Address { get; set; } = ""; public string CityDistrict { get; set; } = ""; public string Phone { get; set; } = ""; public string Email { get; set; } = ""; public TimeOnly Opening { get; set; } public TimeOnly Closing { get; set; } public int SlotMinutes { get; set; } public bool Parking { get; set; } public bool Shower { get; set; } public bool ProShop { get; set; } public bool Wifi { get; set; } public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public string Status { get; set; } = "Active"; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public void Apply(FacilityInput x) { ImageUrl = x.ImageUrl; Name = x.Name.Trim(); Address = x.Address.Trim(); CityDistrict = x.CityDistrict.Trim(); Phone = x.Phone; Email = x.Email; Opening = x.Opening; Closing = x.Closing; SlotMinutes = x.SlotMinutes; Parking = x.Parking; Shower = x.Shower; ProShop = x.ProShop; Wifi = x.Wifi; Latitude = x.Latitude; Longitude = x.Longitude; UpdatedAt = DateTime.UtcNow; } }
public class Court { public int Version { get; set; } = 1; public int Id { get; set; } public int FacilityId { get; set; } public string Name { get; set; } = ""; public string Sport { get; set; } = ""; public string Surface { get; set; } = ""; public bool Indoor { get; set; } public string? Notes { get; set; } public bool Lighting { get; set; } public string Status { get; set; } = "Active"; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; public void Apply(CourtInput x) { Name = x.Name.Trim(); Surface = x.Surface; Indoor = x.Indoor; Notes = x.Notes; Lighting = x.Lighting; } }
public class Policy { public int Id { get; set; } public string Name { get; set; } = ""; public string Scope { get; set; } = ""; public int? FacilityId { get; set; } public string Sport { get; set; } = ""; public decimal Regular { get; set; } public decimal Peak { get; set; } public decimal Weekend { get; set; } public decimal Discount { get; set; } public TimeOnly PeakStart { get; set; } public TimeOnly PeakEnd { get; set; } public DateOnly EffectiveStart { get; set; } public DateOnly? EffectiveEnd { get; set; } public string Status { get; set; } = ""; }
public class Audit { public string Rationale { get; set; } = ""; public int Id { get; set; } public string Entity { get; set; } = ""; public string Action { get; set; } = ""; public int EntityId { get; set; } public int ActorId { get; set; } public DateTime At { get; set; } = DateTime.UtcNow; public string? Before { get; set; } public string After { get; set; } = ""; public static Audit For(string entity, string action, int entityId, int actor, string? before, object after) => new() { Entity = entity, Action = action, EntityId = entityId, ActorId = actor, Before = before, After = JsonSerializer.Serialize(after) }; }
